    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [kdf-a arx]
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseB(pNonce * 0x8EF37108B07C0B4BULL + 0xB459A11789836857ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordB = TwistMix64::DiffuseA(pNonce * 0xBD0812637A8E8A8DULL + 0x990EB4676F7EE21AULL);
    [[maybe_unused]] const std::uint64_t aNonceWordC = TwistMix64::DiffuseC(pNonce * 0xAE18D041D7DDBDB5ULL + 0xBF5ACCEAE39B75F1ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordD = TwistMix64::DiffuseB(pNonce * 0x8A4A1835F75757B1ULL + 0x84B1EBBCB11B656EULL);
    [[maybe_unused]] const std::uint64_t aNonceWordE = TwistMix64::DiffuseA(pNonce * 0xBEDD0245060C8513ULL + 0xC4D3B16DD205DF26ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordF = TwistMix64::DiffuseB(pNonce * 0xCEBE575C4CCF94DDULL + 0xCB275C2A86AE1B11ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordG = TwistMix64::DiffuseB(pNonce * 0xCCD63E36188821CFULL + 0xC5B215C71B1B8E2FULL);
    [[maybe_unused]] const std::uint64_t aNonceWordH = TwistMix64::DiffuseA(pNonce * 0xF7E78A7436FC99FBULL + 0x9C1CA3AC54E6928DULL);
    [[maybe_unused]] const std::uint64_t aNonceWordI = TwistMix64::DiffuseA(pNonce * 0xCB4910077688425FULL + 0xD186153ED393FE6EULL);
