    [[maybe_unused]] const std::uint64_t aNonceWordL = TwistMix64::DiffuseA(pNonce * 0xE31FFFB6EF2C0FFDULL + 0xCFA237CE306C10AAULL);
    [[maybe_unused]] const std::uint64_t aNonceWordM = TwistMix64::DiffuseC(pNonce * 0xA4E6171C6CB3715FULL + 0xB1EBF793D2E0A48EULL);
    [[maybe_unused]] const std::uint64_t aNonceWordN = TwistMix64::DiffuseA(pNonce * 0x83F25751D79746FFULL + 0x8558EF52676F3C2FULL);
    [[maybe_unused]] const std::uint64_t aNonceWordO = TwistMix64::DiffuseB(pNonce * 0xBD5931D2080E546FULL + 0xDAA7D0A2BD080101ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordP = TwistMix64::DiffuseB(pNonce * 0x9823C4539CDD08A7ULL + 0x9A2F7AF4A2F7E4F3ULL);
