            aWandererF = aWandererF + (((RotL64(aCross, 39U) + RotL64(aOrbiterA, 27U)) + aOrbiterI) + aNonceWordP);
            aWandererB = aWandererB ^ ((RotL64(aIngress, 27U) + RotL64(aOrbiterC, 41U)) + aOrbiterD);
            aWandererH = aWandererH + (((RotL64(aCross, 43U) + aOrbiterH) + RotL64(aOrbiterB, 13U)) + RotL64(aCarry, 37U));
            aWandererC = aWandererC ^ (((RotL64(aPrevious, 50U) + aOrbiterK) + RotL64(aOrbiterE, 23U)) + aWUSaltB[((aIndex + 228U)) & S_SALT1]);
            aWandererG = aWandererG + ((RotL64(aScatter, 13U) + RotL64(aOrbiterF, 38U)) + aOrbiterB);
            //
            aCarry = aCarry + (aWandererD ^ RotL64(aWandererG, 36U));
            aCarry = aCarry + (RotL64(aWandererF, 27U) ^ aWandererK);
            aCarry = aCarry + (aWandererH ^ RotL64(aWandererE, 39U));
            aCarry = aCarry + (aWandererJ ^ RotL64(aWandererI, 41U));
