            aScatter = (RotL64(aIngress, 4U) + RotL64(aCarry, 23U)) + (RotL64(aCross, 51U) ^ RotL64(aPrevious, 37U));
            aScatter = TwistMix64::DiffuseB(((aScatter ^ aSeedDomainWordScatter) ^ aNonceWordJ));
            //
            aOrbiterG = ((aWandererC + RotL64(aIngress, 5U)) + 0x3740DE126C8D9511ULL) + aOASaltF[((aIndex + 27U)) & S_SALT1];
            aOrbiterI = ((aWandererA + RotL64(aPrevious, 40U)) + 0xD9DA632AD286631DULL) + aNonceWordA;
            aOrbiterB = (((aWandererI + RotL64(aCross, 11U)) + 0x8A603487361F2D1DULL) + aOASaltC[(((511U - aIndex) + 273U)) & S_SALT1]) + aNonceWordG;
            aOrbiterC = ((aWandererE + RotL64(aScatter, 27U)) + 0x8EF74BB1EAA7257DULL) + aOASaltA[(((511U - aIndex) + 57U)) & S_SALT1];
            aOrbiterK = ((aWandererB + RotL64(aIngress, 21U)) + RotL64(aCarry, 5U)) + 0xAFAA62784765C2F9ULL;
            aOrbiterF = (aWandererF + RotL64(aScatter, 3U)) + 0xCB497A1B5A773EB3ULL;
            aOrbiterJ = (((aWandererD + RotL64(aPrevious, 43U)) + RotL64(aCarry, 23U)) + 0x851E42F715897C6EULL) + aNonceWordE;
            aOrbiterA = ((aWandererG + RotL64(aCross, 23U)) + RotL64(aCarry, 19U)) + 0x1E497E9B0C77C9ABULL;
            aOrbiterD = (aWandererH + RotL64(aIngress, 53U)) + 0xA82E12FBE5268E03ULL;
            aOrbiterH = (aWandererK + RotL64(aCross, 29U)) + 0x9A897F225668ACCAULL;
            aOrbiterE = ((aWandererJ + RotL64(aScatter, 50U)) + 0x3AC22F5B24C80B27ULL) + aOASaltG[((aIndex + 309U)) & S_SALT1];
            //
            aOrbiterG = ((aOrbiterG + aOrbiterI) + 0x7EBFAE6079CDAE7FULL) + aOUSaltH[((aIndex + 2U)) & S_SALT1];
            aOrbiterB = ((aOrbiterB ^ aOrbiterG) ^ 0xD0282F60A77F1E7EULL) ^ aOUSaltE[(((511U - aIndex) + 141U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x902D24AD32379377ULL), 35U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterK) + 0x63D76270B593599DULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterC) ^ 0xA35D7B38D6B318D2ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x909D19E4E3CAC175ULL), 39U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterG) + 0x389A77831D20DBB3ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterF) ^ 0x223812AB6BE7DF8CULL;
