            aWandererA = aWandererA + (((RotL64(aIngress, 29U) + RotL64(aOrbiterD, 34U)) + aOrbiterC) + aWUSaltF[((aIndex + 395U)) & S_SALT1]);
            //
            aCarry = aCarry + (aWandererC ^ RotL64(aWandererB, 51U));
