            //
            aWandererI = aWandererI + (((RotL64(aScatter, 27U) + RotL64(aOrbiterD, 14U)) + aOrbiterB) + aWUSaltG[((aIndex + 493U)) & S_SALT1]);
            aWandererK = aWandererK ^ ((RotL64(aCross, 14U) + aOrbiterF) + RotL64(aOrbiterB, 57U));
            aWandererJ = aWandererJ + ((((RotL64(aPrevious, 57U) + RotL64(aOrbiterH, 35U)) + aOrbiterK) + RotL64(aCarry, 39U)) + aWUSaltE[(((511U - aIndex) + 372U)) & S_SALT1]);
            aWandererE = aWandererE ^ ((RotL64(aIngress, 19U) + aOrbiterD) + RotL64(aOrbiterC, 3U));
            aWandererF = aWandererF + (((RotL64(aCross, 23U) + aOrbiterG) + RotL64(aOrbiterI, 52U)) + aWUSaltB[(((511U - aIndex) + 91U)) & S_SALT1]);
            aWandererC = aWandererC ^ (((RotL64(aIngress, 37U) + RotL64(aOrbiterA, 29U)) + aOrbiterF) + aWUSaltC[((aIndex + 101U)) & S_SALT1]);
