            aOrbiterK = ((aWandererD + RotL64(aIngress, 37U)) + 0xA9F4C1F982831259ULL) + aOASaltE[(((511U - aIndex) + 459U)) & S_SALT1];
            aOrbiterF = ((aWandererI + RotL64(aPrevious, 3U)) + RotL64(aCarry, 57U)) + 0x5B8E5B26AB776A60ULL;
            aOrbiterD = (aWandererC + RotL64(aScatter, 11U)) + 0x7708EDB4C7CB9AF2ULL;
            aOrbiterB = ((aWandererG + RotL64(aIngress, 41U)) + RotL64(aCarry, 35U)) + 0xCB9E1D5C985CDCA7ULL;
            aOrbiterC = ((aWandererK + RotL64(aPrevious, 53U)) + 0xBE8B5C8AB5FD4BE4ULL) + aOASaltH[((aIndex + 206U)) & S_SALT1];
            aOrbiterJ = (aWandererB + RotL64(aScatter, 19U)) + 0x771D2A6944DE75C8ULL;
            aOrbiterA = ((aWandererH + RotL64(aCross, 58U)) + RotL64(aCarry, 13U)) + 0xD6F472337EB85874ULL;
