            aOrbiterG = ((aOrbiterG + aOrbiterA) + 0x165EE6E5F4479AEFULL) + aOUSaltA[((aIndex + 194U)) & S_SALT1];
            aOrbiterK = ((aOrbiterK ^ aOrbiterG) ^ 0xD1E7BA7C7C5336D4ULL) ^ aOUSaltF[(((511U - aIndex) + 91U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x80D1AA0D68E965EFULL), 29U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterB) + 0x0D41A218FBBD765DULL) + aOUSaltC[((aIndex + 479U)) & S_SALT1];
